(21, 2, NOW()), (21, 23, NOW()), -- Marble Mt -> Nature, Ancient
(23, 1, NOW()), (23, 15, NOW()), (23, 28, NOW()), -- Ba Na -> Nature, Modern, Theme Park
(83, 10, NOW()), (83, 15, NOW()); -- Fireworks -> Culture, Modern

-- Randomly fill remaining to ensure ~100 pivot rows
INSERT INTO location_tags (location_id, tag_id, created_at)
SELECT 
    l.id, 
    (random() * 29 + 1)::int, 
    NOW()
FROM locations l
CROSS JOIN generate_series(1, 2)
ON CONFLICT DO NOTHING;

-- 3. LOCATION_AMENITIES (Pivots)
INSERT INTO location_amenities (location_id, amenity_id, created_at)
SELECT 
    l.id, 
    (random() * 19 + 1)::int, 
    NOW()
FROM locations l
CROSS JOIN generate_series(1, 3)
ON CONFLICT DO NOTHING;
